<?= $this->extend('layouts/public') ?><?= $this->section('content') ?>
<section class="page-header"><div class="container narrow"><p class="eyebrow">Applicant dashboard</p><h1>Your admission applications</h1><p class="lead">Continue a saved draft or start a new application for an open programme.</p></div></section>
<section class="section"><div class="container narrow content-stack"><?php if (session('message')): ?><p class="notice" role="status"><?= esc(session('message')) ?></p><?php endif ?><?php if (! empty($activeOffer)): ?><p class="notice">You have an active admission offer: <a href="<?= site_url('applicant/offers') ?>"><?= esc($activeOffer['offer_reference']) ?></a></p><?php endif ?><?php if (! empty($publishedListEntries)): ?><p class="notice">Your offer appears on a published admission list: <a href="<?= public_site_url('admission_list', [$publishedListEntries[0]['public_token']]) ?>"><?= esc($publishedListEntries[0]['title']) ?></a></p><?php endif ?><section><h2>Notifications</h2><?php if($notifications===[]):?><div class="empty">No notifications yet.</div><?php else:?><ul class="record-list"><?php foreach($notifications as $notification):?><li><strong><?= esc($notification['title']) ?></strong><br><?= esc($notification['body']) ?><?php if($notification['action_url']):?> <a class="text-link" href="<?= esc(site_url(ltrim($notification['action_url'],'/'))) ?>">View update</a><?php endif?></li><?php endforeach?></ul><?php endif?></section><section><h2>Your applications</h2><?php if ($drafts === []): ?><div class="empty">You have not started an application.</div><?php else: ?><div class="admin-grid"><?php foreach ($drafts as $draft): ?><article class="admin-card"><span class="badge"><?= esc(str_replace('_',' ',$draft['status'])) ?></span><h3>Application <?= esc($draft['application_number']?:'#'.$draft['id']) ?></h3><p>Biodata: <?= esc(str_replace('_',' ',$draft['biodata_status'])) ?></p><a class="button" href="<?= esc(site_url('applicant/applications/'.$draft['public_token'])) ?>">Continue application</a></article><?php endforeach ?></div><?php endif ?></section><section><h2>Open programmes</h2><?php if ($openProgrammes === []): ?><div class="empty">No programme is currently accepting applications.</div><?php else: ?><div class="admin-grid"><?php foreach ($openProgrammes as $programme): ?><article class="admin-card"><h3><?= esc($programme['programme_name']) ?></h3><form method="post" action="<?= site_url('applicant/applications') ?>"><?= csrf_field() ?><input type="hidden" name="programme_opening_id" value="<?= esc($programme['id']) ?>"><button>Start or continue</button></form></article><?php endforeach ?></div><?php endif ?></section></div></section>
<?= $this->endSection() ?>
